async function runQueue(){if(running)return;running=true;try{for(;;){const r=records.find(r=>r.state==='queued');if(!r)break;r.state='processing';r.extraWarnings=[];if(current===r)show(r);renderList();status(`${r.file.name} 준비 중…`,3);let timeout;
try{const task=(async()=>{await prepare(r);if(current===r){renderPreview();$('pageSelect').replaceChildren(...r.pages.map((p,i)=>new Option(`${i+1} / ${r.pages.length}쪽`,i)))}const texts=[],confidence=[];for(let i=0;i<r.pages.length;i++){const out=await recognizePage(r,i);texts.push(out.text);confidence.push(out.confidence)}return {text:texts.join('\n\n'),confidence:confidence.reduce((a,b)=>a+b,0)/confidence.length}})();const result=await Promise.race([task,new Promise((_,reject)=>timeout=setTimeout(()=>reject(Error('인식 시간이 초과됐어요. 영역을 좁히거나 직접 입력해 주세요.')),120000))]);r.confidence=result.confidence;applyInfo(r,C.parse(result.text));if(result.confidence<65)r.warnings.unshift('사진의 인식 신뢰도가 낮아요. 영역 선택으로 영수증만 지정하면 더 잘 읽을 수 있어요.');r.state='done'}catch(e){r.state='error';r.warnings=[`인식 실패: ${e.message||e}`,'직접 입력하거나 캡처 도구에서 복사한 텍스트를 붙여넣을 수 있어요.'];toast(`${r.file.name}\n${r.warnings[0]}`);if(worker){await worker.terminate().catch(()=>{});worker=null;workerPromise=null}}finally{clearTimeout(timeout)}if(current===r){current=null;show(r)}renderList()}}finally{running=false;status('인식이 끝났어요. 원본과 대조해 주세요.',100)}}
async function addFiles(files){saveFields();const errors=[];for(const file of files){if(records.length>=50){errors.push('한 번에 최대 50개까지 추가할 수 있어요.');break}if(!/\.(jpe?g|png|pdf)$/i.test(file.name)){errors.push(`${file.name}: JPG·JPEG·PNG·PDF만 지원해요.`);continue}if(!file.size||file.size>20*1024*1024){errors.push(`${file.name}: 0바이트이거나 20MB를 초과했어요.`);continue}if(records.some(r=>r.file.name===file.name&&r.file.size===file.size&&r.file.lastModified===file.lastModified))continue;const r={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random()),file,state:'queued',date:'',amount:'',people:'',category:'',...defaults,verified:false,text:'',items:[],notices:[],warnings:[],extraWarnings:[],pages:[],crops:{},page:0};records.push(r)}if(!current&&records.length)show(records[0]);renderList();if(errors.length)toast(errors.join('\n'));runQueue()}
function requireCurrent(){saveFields();if(!current)throw Error('영수증을 먼저 추가해 주세요.');if(['queued','processing'].includes(current.state))throw Error('인식이 끝난 후 시도해 주세요.');return current}
function requireVerified(r){if(!r.verified)throw Error('원본과 대조한 뒤 확인란을 체크해 주세요.');C.filename(r.date,r.amount,r.file.name);C.expense(r);for(const item of r.items)if(item.include&&(!Number.isInteger(Number(item.qty))||Number(item.qty)<1||Number(item.qty)>999))throw Error('포함된 품목의 수량을 1~999 사이 정수로 입력해 주세요.')}
async function copy(t){try{if(!navigator.clipboard)throw Error();await navigator.clipboard.writeText(t)}catch{const ta=document.createElement('textarea');ta.value=t;ta.style.position='fixed';ta.style.left='-9999px';document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();if(!ok)throw Error('자동 복사가 제한되어 있어요. 화면의 문구를 선택해 Ctrl+C로 복사해 주세요.')}toast('경비 문구를 복사했어요.')}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
// Uncompressed ZIP writer. Original receipt bytes are preserved exactly.
const crcTable=Array.from({length:256},(_,i)=>{let c=i;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0});
function crc32(a){let c=0xffffffff;for(const b of a)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0}
function zip(files){const chunks=[],central=[];let offset=0;const enc=new TextEncoder();for(const f of files){const name=enc.encode(f.name),data=f.data;const crc=crc32(data),head=new Uint8Array(30+name.length),v=new DataView(head.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,0x5821,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);head.set(name,30);chunks.push(head,data);const cen=new Uint8Array(46+name.length),d=new DataView(cen.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint16(14,0x5821,true);d.setUint32(16,crc,true);d.setUint32(20,data.length,true);d.setUint32(24,data.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);cen.set(name,46);central.push(cen);offset+=head.length+data.length}const length=central.reduce((s,c)=>s+c.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,length,true);v.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'})}
function safe(fn){return async(...args)=>{try{await fn(...args)}catch(e){toast(e.message||String(e))}}}
$('addBtn').onclick=e=>{e.stopPropagation();$('fileInput').click()};$('dropZone').onclick=()=>$('fileInput').click();$('dropZone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('fileInput').click()}};$('fileInput').onchange=e=>{addFiles([...e.target.files]);e.target.value=''};
for(const name of ['dragenter','dragover'])$('dropZone').addEventListener(name,e=>{e.preventDefault();$('dropZone').classList.add('drag')});for(const name of ['dragleave','drop'])$('dropZone').addEventListener(name,e=>{e.preventDefault();$('dropZone').classList.remove('drag')});$('dropZone').addEventListener('drop',e=>addFiles([...e.dataTransfer.files]));document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('drop',e=>e.preventDefault());
for(const k of ['date','amount','people','category','cell','representative','client','hasClient'])$(k).addEventListener('input',()=>{dirty();saveFields();outputs()});
$('verified').onchange=safe(()=>{saveFields();if(current.verified){try{requireVerified(current)}catch(e){current.verified=false;$('verified').checked=false;throw e}}refreshBadges();renderList()});
$('rawText').oninput=()=>{dirty();if(current)current.text=$('rawText').value};
$('parseBtn').onclick=safe(()=>{const r=requireCurrent();applyInfo(r,C.parse($('rawText').value));r.state='done';current=null;show(r);toast('텍스트를 다시 분석했어요.')});
$('addItem').onclick=()=>{if(!current)return;current.items.push({name:'',qty:1,include:true,basis:'직접 입력'});dirty();renderItems()};
$('applyQty').onclick=safe(()=>{const r=requireCurrent();const selected=r.items.filter(x=>x.include);if(!selected.length)throw Error('인원에 포함할 품목을 체크해 주세요.');for(const x of selected)if(!Number.isInteger(Number(x.qty))||x.qty<1||x.qty>999)throw Error('품목 수량을 1~999 사이 정수로 입력해 주세요.');const sum=selected.reduce((s,x)=>s+Number(x.qty),0);if(sum>999)throw Error('총 인원은 999명까지 입력할 수 있어요.');$('people').value=String(sum);dirty();saveFields();outputs();toast(`품목 수량 ${sum}개를 총 ${sum}명으로 적용했어요.`)});
$('copyBtn').onclick=safe(async()=>{const r=requireCurrent();requireVerified(r);await copy(C.expense(r))});
$('saveBtn').onclick=safe(async()=>{const r=requireCurrent();requireVerified(r);download(r.file,C.filename(r.date,r.amount,r.file.name));toast('새 이름의 사본을 저장했어요. 원본은 그대로예요.')});
$('bulkCopy').onclick=safe(async()=>{saveFields();const rows=records.filter(r=>r.verified);if(!rows.length)throw Error('확인 완료한 영수증이 없어요.');rows.forEach(requireVerified);await copy(rows.map(C.expense).join('\n'))});
$('bulkSave').onclick=safe(async()=>{saveFields();const rows=records.filter(r=>r.verified);if(!rows.length)throw Error('확인 완료한 영수증이 없어요.');rows.forEach(requireVerified);if(rows.reduce((s,r)=>s+r.file.size,0)>100*1024*1024)throw Error('ZIP 저장은 한 번에 100MB까지 지원해요. 개별 저장해 주세요.');const names=C.uniqueNames(rows.map(r=>C.filename(r.date,r.amount,r.file.name))),files=[];for(let i=0;i<rows.length;i++)files.push({name:names[i],data:new Uint8Array(await rows[i].file.arrayBuffer())});files.push({name:'경비문구.txt',data:new TextEncoder().encode('\ufeff'+rows.map((r,i)=>names[i]+'\r\n'+C.expense(r)).join('\r\n\r\n'))});download(zip(files),'영수증_정리.zip');toast(`${rows.length}개 영수증과 경비 문구를 ZIP으로 저장했어요.`)});
$('clearBtn').onclick=()=>{if(!records.length)return;if(running){toast('인식이 끝난 뒤 목록을 비워 주세요.');return}if(!confirm('추가한 영수증과 편집 내용을 목록에서 지울까요? 원본 파일은 유지됩니다.'))return;records.forEach(disposeRecord);records=[];current=null;show(null);status('목록을 비웠어요.',0)};
$('pageSelect').onchange=()=>{if(current){current.page=Number($('pageSelect').value);renderPreview()}};
$('retryBtn').onclick=safe(()=>{const r=requireCurrent();if(running)throw Error('현재 인식이 끝난 뒤 다시 시도해 주세요.');r.state='queued';r.verified=false;runQueue()});
$('rotateBtn').onclick=safe(async()=>{const r=requireCurrent();if(running)throw Error('현재 인식이 끝난 뒤 회전해 주세요.');const index=r.page||0,img=await loadImage(r.pages[index].url),canvas=document.createElement('canvas');canvas.width=img.naturalHeight;canvas.height=img.naturalWidth;const ctx=canvas.getContext('2d');ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(Math.PI/2);ctx.drawImage(img,-img.naturalWidth/2,-img.naturalHeight/2);const previous=r.pages[index].url;r.pages[index].url=await canvasURL(canvas);r.pages[index].nativeText='';delete r.crops[index];if(index===0)r.thumb=r.pages[index].url;URL.revokeObjectURL(previous);dirty();renderPreview();renderList();toast('미리보기를 회전했어요. ‘다시 인식’을 눌러 주세요. 저장되는 원본 파일 내용은 바뀌지 않아요.')});
$('cropBtn').onclick=safe(()=>{const r=requireCurrent();if(!r.pages.length)throw Error('미리보기가 없는 파일은 영역을 선택할 수 없어요.');cropMode=!cropMode;$('cropBtn').classList.toggle('primary',cropMode);$('imageStage').style.cursor=cropMode?'crosshair':'default';if(cropMode)toast('영수증이 있는 부분을 드래그해 주세요. 지정 후 ‘다시 인식’을 누르세요.')});
const pointer=e=>{const b=$('previewImage').getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))}};
$('imageStage').addEventListener('pointerdown',e=>{if(!cropMode||!current)return;e.preventDefault();cropStart=pointer(e);$('imageStage').setPointerCapture(e.pointerId)});
$('imageStage').addEventListener('pointermove',e=>{if(!cropStart||!current)return;const end=pointer(e);current.crops[current.page||0]={x:Math.min(cropStart.x,end.x),y:Math.min(cropStart.y,end.y),w:Math.abs(end.x-cropStart.x),h:Math.abs(end.y-cropStart.y)};renderCrop()});
$('imageStage').addEventListener('pointerup',e=>{if(!cropStart)return;cropStart=null;const crop=current.crops[current.page||0];if(!crop||crop.w<.05||crop.h<.05){delete current.crops[current.page||0];toast('조금 더 넓은 영역을 선택해 주세요.')}else{dirty();toast('영역을 지정했어요. ‘다시 인식’을 눌러 주세요.')}renderCrop()});
$('resetCrop').onclick=()=>{if(current){delete current.crops[current.page||0];dirty();renderCrop();toast('영역을 초기화했어요. 다시 인식할 수 있어요.')}};
$('helpBtn').onclick=()=>$('helpDialog').showModal();$('helpDialog').querySelector('.close-dialog').onclick=()=>$('helpDialog').close();$('remember').onchange=()=>{if($('remember').checked){saveFields();remember()}else{try{localStorage.removeItem('receipt-desk-defaults')}catch{}}};
$('offlineDownload').onclick=safe(()=>{const clone=document.documentElement.cloneNode(true);clone.querySelector('#fileList').replaceChildren();clone.querySelector('#itemsBody').replaceChildren();clone.querySelector('#itemsCount').textContent='0개 상품';clone.querySelector('#itemsEmpty').classList.remove('hidden');for(const e of clone.querySelectorAll('input')){e.removeAttribute('value');e.removeAttribute('checked')}clone.querySelector('#rawText').textContent='';clone.querySelector('#previewImage').removeAttribute('src');clone.querySelector('#cropOverlay').classList.add('hidden');clone.querySelector('#imageStage').classList.add('hidden');clone.querySelector('#previewEmpty').classList.remove('hidden');clone.querySelector('#count').textContent='0';clone.querySelector('#listEmpty').classList.remove('hidden');clone.querySelector('#expense').textContent='인원을 확인하면 경비 문구가 여기에 표시돼요.';clone.querySelector('#filename').textContent='날짜_금액.jpeg';clone.querySelector('#benefits').textContent='인식 후 관련 문구를 표시합니다.';clone.querySelector('#warnings').textContent='영수증을 추가하면 자동으로 내용을 읽습니다.';clone.querySelector('#confidence').textContent='';clone.querySelector('#editor').dataset.disabled='true';clone.querySelector('#helpDialog').removeAttribute('open');clone.querySelector('#toast').classList.add('hidden');clone.querySelector('#verifiedBadge').textContent='확인 대기';clone.querySelector('#previewBadge').textContent='파일을 추가해 주세요.';clone.querySelector('#statusText').textContent='준비됐어요.';clone.querySelector('#progress').style.width='0%';download(new Blob(['<!doctype html>\n',clone.outerHTML],{type:'text/html;charset=utf-8'}),'ReceiptDesk_Offline.html');toast('OCR을 포함한 오프라인 HTML을 저장했어요.')});
for(const k of ['cell','representative','client'])$(k).value=defaults[k];$('hasClient').checked=defaults.hasClient;
window.addEventListener('beforeunload',e=>{if(records.length){e.preventDefault();e.returnValue=''}});
